import React from "react";
import { FaComments } from "react-icons/fa6";
import ChatPanel from "./ChatPanel";
import { useChat } from "./ChatContext";

const FloatingChatFAB = () => {
  const { closeChat, isOpen, openChat, pageContext } = useChat();

  return (
    <>
      {!isOpen && (
        <button
          type="button"
          onClick={openChat}
          className="fixed bottom-6 right-6 z-[1000] inline-flex h-16 w-16 items-center justify-center rounded-full bg-[#0D9488] text-2xl text-white shadow-2xl shadow-teal-950/30 transition hover:-translate-y-1 hover:bg-[#134E4A] focus:outline-none focus:ring-4 focus:ring-[#67E8F9]/50"
          aria-label="Open CareBridge AI chat"
        >
          <FaComments />
        </button>
      )}

      {isOpen && (
        <div className="fixed inset-0 z-[1001]">
          <button
            type="button"
            className="absolute inset-0 h-full w-full bg-[#134E4A]/45 backdrop-blur-sm"
            onClick={closeChat}
            aria-label="Close CareBridge AI backdrop"
          />
          <section className="absolute bottom-0 right-0 flex h-[min(760px,calc(100vh-2rem))] w-full max-w-[520px] flex-col overflow-hidden rounded-t-[1.5rem] bg-white shadow-2xl shadow-teal-950/25 sm:bottom-6 sm:right-6 sm:h-[min(760px,calc(100vh-3rem))] sm:w-[520px] sm:rounded-[1.5rem]">
            <ChatPanel
              initialContext={pageContext}
              isFloating
              onClose={closeChat}
            />
          </section>
        </div>
      )}
    </>
  );
};

export default FloatingChatFAB;
