import axios from "axios";
import Cookies from "js-cookie";
import BaseUrl from "../Api/baseurl";

const demoConversationId = "demo-agent-conversation";
const anonymousSessionKey = "carebridge-agent-anonymous-session";

const getAuthToken = () => Cookies.get("patient_token") || Cookies.get("token") || "";

const isDemoToken = (token) => Boolean(token) && String(token).startsWith("demo-token-");

export const isLoggedIn = () => {
  const token = getAuthToken();
  return Boolean(token) && !isDemoToken(token);
};

export const getAnonymousSessionId = () => {
  let existing = window.localStorage.getItem(anonymousSessionKey);
  if (existing) return existing;
  existing =
    window.crypto?.randomUUID?.() ||
    `anon-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  window.localStorage.setItem(anonymousSessionKey, existing);
  return existing;
};

export const getAgentConversationKey = () =>
  `carebridge-agent-conversation-${
    Cookies.get("patient_uid") ||
    Cookies.get("patient_username") ||
    Cookies.get("uid") ||
    getAnonymousSessionId()
  }`;

const demoReply = (message, context = null) => {
  const text = String(message || "").toLowerCase();

  if (context?.type === "doctor") {
    return {
      reply:
        `You are viewing ${context.doctorName || "this doctor"}. I can help compare fit, explain the specialty, and prepare booking questions. In demo mode, live tool calls are disabled, but this profile link is available: ${context.profileUrl || `/doctors/${context.doctorId}`}.`,
      conversationId: demoConversationId,
      actions: [
        {
          type: "doctors",
          doctors: [
            {
              id: context.doctorId,
              name: context.doctorName || "Selected doctor",
              specialty: context.specialty || "CareBridge specialist",
              hospitalName: context.hospitalName || "CareBridge",
              profileUrl: context.profileUrl || `/doctors/${context.doctorId}`,
            },
          ],
        },
      ],
    };
  }

  if (/(fever|cold|cough|headache|pain|rash|vomit|diarrhea|sneez|breath)/.test(text)) {
    return {
      reply:
        "I can help you think through symptoms, but this is not a diagnosis. For mild symptoms, rest, hydrate, track fever or pain, and avoid self-medicating. If you have chest pain, severe breathing difficulty, fainting, confusion, severe bleeding, or symptoms are worsening quickly, seek urgent care now.\n\nFor live symptom matching and doctor recommendations, enable Firebase Auth and set OPENAI_API_KEY in Cloud Functions.",
      conversationId: demoConversationId,
      actions: [],
    };
  }

  if (
    /(doctor|appointment|book|slot|specialist|neurologist|neurology|cardiologist|cardiology|dermatologist|dermatology|orthopedic|orthopedics|pediatrician|pediatrics)/.test(
      text,
    )
  ) {
    return {
      reply:
        "I can help find doctors and prepare bookings once the live agent is connected. In demo mode, you can still use the Hospitals and Appointments pages to browse CareBridge doctors and slots.",
      conversationId: demoConversationId,
      actions: [
        {
          type: "doctors",
          doctors: [
            {
              id: "doctor-amelia-shah",
              name: "Dr. Amelia Shah",
              specialty: "Cardiology",
              hospitalName: "CareBridge Central Hospital",
              profileUrl: "/doctors/doctor-amelia-shah",
              location: "New Delhi",
            },
            {
              id: "doctor-nisha-rao",
              name: "Dr. Nisha Rao",
              specialty: "Neurology",
              hospitalName: "CareBridge Gurugram MedTech Hospital",
              profileUrl: "/doctors/doctor-nisha-rao",
              location: "Gurugram",
            },
          ],
        },
      ],
    };
  }

  if (/(test|lab|blood|mri|ecg)/.test(text)) {
    return {
      reply:
        "CareBridge supports lab and diagnostic test booking through hospital profiles. The live AI agent can list tests, check slot capacity, and book after your confirmation once connected.",
      conversationId: demoConversationId,
      actions: [],
    };
  }

  return {
    reply:
      "Hi, I am CareBridge AI. Ask me about symptoms, doctors, appointments, lab tests, or contacting a hospital. Demo mode is active, so live AI tool calls are disabled until Firebase Auth and OPENAI_API_KEY are configured.",
    conversationId: demoConversationId,
    actions: [],
  };
};

export const sendAgentMessage = async ({message, conversationId, context = null}) => {
  const token = getAuthToken();
  if (isDemoToken(token)) {
    await new Promise((resolve) => setTimeout(resolve, 450));
    return demoReply(message, context);
  }

  try {
    const response = await axios.post(
      `${BaseUrl}agent/chat`,
      {
        message,
        conversationId,
        context,
        anonymousSessionId: getAnonymousSessionId(),
      },
      {
        headers: {
          ...(token ? {Authorization: `Bearer ${token}`} : {}),
          "Content-Type": "application/json",
        },
      },
    );

    return response.data;
  } catch (error) {
    const unavailableBecauseLocalKeyMissing =
      !token &&
      error?.response?.status === 503 &&
      String(error?.response?.data?.error || "").includes("OPENAI_API_KEY");
    const localAnonymousBackendUnavailable =
      !token &&
      process.env.NODE_ENV !== "production" &&
      (!error.response || [404, 503].includes(error.response.status));

    if (unavailableBecauseLocalKeyMissing || localAnonymousBackendUnavailable) {
      return demoReply(message, context);
    }

    throw error;
  }
};
