import React, { useEffect, useMemo, useRef } from "react";
import { Link } from "react-router-dom";
import {
  FaArrowUpRightFromSquare,
  FaCalendarCheck,
  FaHospital,
  FaPaperPlane,
  FaRotateRight,
  FaShieldHeart,
  FaUserDoctor,
  FaVialCircleCheck,
  FaXmark,
} from "react-icons/fa6";
import { useChat } from "./ChatContext";

const starterPrompts = [
  "I have fever and body ache. What should I do?",
  "Find a neurologist for migraine in Gurugram.",
  "Show lab tests at the default hospital.",
];

const doctorPrompt = (context) =>
  `I am viewing ${context.doctorName || "this doctor"}. Can you help me understand whether this doctor is a good fit?`;

const ActionPanel = ({ actions = [] }) => {
  const visibleActions = actions.filter(Boolean);
  if (!visibleActions.length) return null;

  return (
    <div className="mt-3 space-y-3">
      {visibleActions.map((action, index) => {
        if (action.type === "loginRequired") {
          return (
            <Link
              key={`${action.type}-${index}`}
              to={action.loginUrl || "/user/login"}
              className="inline-flex min-h-11 items-center justify-center gap-2 rounded-2xl bg-[#F59E0B] px-4 text-sm font-black text-[#134E4A] shadow-lg shadow-amber-900/10"
            >
              Log in to continue
              <FaArrowUpRightFromSquare />
            </Link>
          );
        }

        if (action.type === "doctors" && action.doctors?.length) {
          return (
            <div key={`${action.type}-${index}`} className="grid gap-2 sm:grid-cols-2">
              {action.doctors.slice(0, 4).map((doctor) => {
                const profileUrl = doctor.profileUrl || (doctor.id ? `/doctors/${doctor.id}` : "");
                const content = (
                  <div className="flex items-start gap-3">
                    <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#ECFEFF] text-[#0D9488]">
                      <FaUserDoctor />
                    </span>
                    <div className="min-w-0">
                      <p className="truncate text-sm font-black">{doctor.name}</p>
                      <p className="mt-1 text-xs font-bold text-[#0D9488]">{doctor.specialty}</p>
                      <p className="mt-1 text-xs font-semibold text-[#134E4A]/60">
                        {doctor.hospitalName || doctor.location}
                      </p>
                    </div>
                  </div>
                );

                return profileUrl ? (
                  <Link
                    key={doctor.id || doctor.username}
                    to={profileUrl}
                    className="rounded-2xl border border-[#67E8F9]/60 bg-white p-3 text-[#134E4A] transition hover:border-[#0D9488]"
                  >
                    {content}
                  </Link>
                ) : (
                  <div
                    key={doctor.id || doctor.username}
                    className="rounded-2xl border border-[#67E8F9]/60 bg-white p-3 text-[#134E4A]"
                  >
                    {content}
                  </div>
                );
              })}
            </div>
          );
        }

        if (action.type === "doctorSlots" && action.slots?.length) {
          return (
            <div key={`${action.type}-${index}`} className="grid gap-2 sm:grid-cols-3">
              {action.slots.slice(0, 6).map((slot) => (
                <div key={slot.id} className="rounded-2xl border border-[#67E8F9]/60 bg-white p-3 text-[#134E4A]">
                  <p className="text-xs font-black uppercase tracking-[0.14em] text-[#0D9488]">{slot.date}</p>
                  <p className="mt-1 text-sm font-black">{slot.startTime}</p>
                </div>
              ))}
            </div>
          );
        }

        if (action.type === "labTests" && action.tests?.length) {
          return (
            <div key={`${action.type}-${index}`} className="grid gap-2 sm:grid-cols-2">
              {action.tests.slice(0, 4).map((test) => (
                <div key={test.id} className="rounded-2xl border border-[#67E8F9]/60 bg-white p-3 text-[#134E4A]">
                  <div className="flex items-start gap-3">
                    <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#ECFEFF] text-[#0D9488]">
                      <FaVialCircleCheck />
                    </span>
                    <div>
                      <p className="text-sm font-black">{test.name}</p>
                      <p className="mt-1 text-xs font-bold text-[#0D9488]">{test.category}</p>
                      <p className="mt-1 text-xs font-semibold text-[#134E4A]/60">Rs. {test.price || 0}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          );
        }

        if (action.type === "labTestSlots" && action.slots?.length) {
          return (
            <div key={`${action.type}-${index}`} className="grid gap-2 sm:grid-cols-3">
              {action.slots.slice(0, 6).map((slot) => (
                <div key={slot.id} className="rounded-2xl border border-[#67E8F9]/60 bg-white p-3 text-[#134E4A]">
                  <p className="text-xs font-black uppercase tracking-[0.14em] text-[#0D9488]">{slot.date}</p>
                  <p className="mt-1 text-sm font-black">{slot.startTime}</p>
                  <p className="mt-1 text-xs font-semibold text-[#134E4A]/60">{slot.availableCapacity} left</p>
                </div>
              ))}
            </div>
          );
        }

        if (action.type === "appointmentBooked") {
          return (
            <div key={`${action.type}-${index}`} className="rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-emerald-900">
              <p className="flex items-center gap-2 text-sm font-black">
                <FaCalendarCheck />
                Appointment request created
              </p>
              <p className="mt-1 text-xs font-semibold">ID: {action.appointment.appointmentId}</p>
            </div>
          );
        }

        if (action.type === "labTestBooked") {
          return (
            <div key={`${action.type}-${index}`} className="rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-emerald-900">
              <p className="flex items-center gap-2 text-sm font-black">
                <FaVialCircleCheck />
                Test booking confirmed
              </p>
              <p className="mt-1 text-xs font-semibold">ID: {action.booking.bookingId}</p>
            </div>
          );
        }

        if (action.type === "hospitalContacted") {
          return (
            <div key={`${action.type}-${index}`} className="rounded-2xl border border-[#67E8F9]/60 bg-white p-4 text-[#134E4A]">
              <p className="flex items-center gap-2 text-sm font-black">
                <FaHospital />
                Hospital contact request sent
              </p>
            </div>
          );
        }

        return null;
      })}
    </div>
  );
};

const ChatPanel = ({ initialContext = null, isFloating = false, onClose = null }) => {
  const {
    error,
    input,
    messages,
    pageContext,
    resetConversation,
    sendMessage,
    sending,
    setInput,
    username,
  } = useChat();
  const listRef = useRef(null);
  const activeContext = initialContext || pageContext;

  const canSend = useMemo(() => input.trim().length > 0 && !sending, [input, sending]);
  const prompts = useMemo(
    () =>
      activeContext?.type === "doctor"
        ? [doctorPrompt(activeContext), "Show this doctor's available appointment slots.", ...starterPrompts.slice(0, 2)]
        : starterPrompts,
    [activeContext],
  );

  useEffect(() => {
    listRef.current?.scrollTo({
      top: listRef.current.scrollHeight,
      behavior: "smooth",
    });
  }, [messages, sending]);

  const handleSend = (text) => sendMessage(text, activeContext);

  return (
    <div className={`flex h-full min-h-0 flex-col bg-white text-[#134E4A] ${isFloating ? "" : "rounded-[2rem] border border-[#67E8F9]/50 shadow-xl shadow-teal-900/10"}`}>
      <header className={`${isFloating ? "rounded-t-[1.5rem]" : "rounded-t-[2rem]"} bg-[#134E4A] p-4 text-white sm:p-5`}>
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <p className="inline-flex items-center gap-2 text-xs font-black uppercase tracking-[0.18em] text-[#67E8F9]">
              <FaShieldHeart />
              CareBridge AI
            </p>
            <h2 className="mt-1 text-2xl font-black leading-tight">Ask, choose care, and confirm bookings.</h2>
            <p className="mt-2 text-xs font-semibold text-cyan-50/75">
              Signed in as {username}
            </p>
          </div>
          <div className="flex shrink-0 gap-2">
            <button
              type="button"
              onClick={resetConversation}
              className="inline-flex h-10 w-10 items-center justify-center rounded-2xl bg-white/10 text-[#67E8F9] transition hover:bg-white/15"
              aria-label="Start a new chat"
            >
              <FaRotateRight />
            </button>
            {onClose && (
              <button
                type="button"
                onClick={onClose}
                className="inline-flex h-10 w-10 items-center justify-center rounded-2xl bg-white/10 text-white transition hover:bg-white/15"
                aria-label="Close chat"
              >
                <FaXmark />
              </button>
            )}
          </div>
        </div>

        {activeContext?.type === "doctor" && (
          <div className="mt-4 rounded-2xl border border-white/15 bg-white/10 p-3 text-sm font-bold text-cyan-50">
            Viewing {activeContext.doctorName || "this doctor"}. I can keep answers focused on this profile.
            {activeContext.profileUrl && (
              <Link to={activeContext.profileUrl} className="ml-2 font-black text-[#67E8F9]">
                Open profile
              </Link>
            )}
          </div>
        )}
      </header>

      <div className={`${isFloating ? "grid flex-1 grid-rows-[1fr_auto_auto]" : "grid min-h-[600px] flex-1 grid-rows-[1fr_auto_auto]"} min-h-0`}>
        <div ref={listRef} className="min-h-0 flex-1 space-y-4 overflow-y-auto bg-[#ECFEFF]/45 p-4 sm:p-5">
          {messages.map((message, index) => {
            const mine = message.role === "user";
            return (
              <div key={`${message.role}-${index}`} className={`flex ${mine ? "justify-end" : "justify-start"}`}>
                <div className={`max-w-[92%] ${mine ? "text-right" : "text-left"} ${isFloating ? "sm:max-w-[88%]" : "sm:max-w-[78%]"}`}>
                  <div
                    className={`rounded-2xl px-4 py-3 text-sm font-semibold leading-6 shadow-sm ${
                      mine
                        ? "bg-[#0D9488] text-white"
                        : "border border-[#67E8F9]/50 bg-white text-[#134E4A]"
                    }`}
                  >
                    <p className="whitespace-pre-wrap">{message.text}</p>
                  </div>
                  {!mine && <ActionPanel actions={message.actions} />}
                </div>
              </div>
            );
          })}

          {sending && (
            <div className="flex justify-start">
              <div className="rounded-2xl border border-[#67E8F9]/50 bg-white px-4 py-3 text-sm font-black text-[#0D9488] shadow-sm">
                Thinking...
              </div>
            </div>
          )}
        </div>

        {error && (
          <div className="border-t border-amber-200 bg-amber-50 px-5 py-3 text-sm font-bold text-amber-900">
            {error}
          </div>
        )}

        <div className="border-t border-[#67E8F9]/45 bg-white p-4">
          <div className="mb-3 flex gap-2 overflow-x-auto pb-1">
            {prompts.map((prompt) => (
              <button
                key={prompt}
                type="button"
                onClick={() => handleSend(prompt)}
                disabled={sending}
                className="shrink-0 rounded-full border border-[#67E8F9]/70 bg-[#ECFEFF] px-4 py-2 text-xs font-black text-[#134E4A] transition hover:border-[#0D9488] hover:bg-white disabled:opacity-60"
              >
                {prompt}
              </button>
            ))}
          </div>
          <div className="flex gap-3">
            <textarea
              value={input}
              onChange={(event) => setInput(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter" && !event.shiftKey) {
                  event.preventDefault();
                  handleSend(input);
                }
              }}
              rows={1}
              placeholder="Message CareBridge AI"
              className="max-h-32 min-h-12 flex-1 resize-none rounded-2xl border border-[#67E8F9]/70 bg-[#ECFEFF] px-4 py-3 text-sm font-semibold outline-none focus:border-[#0D9488] focus:bg-white focus:ring-4 focus:ring-[#67E8F9]/30"
            />
            <button
              type="button"
              onClick={() => handleSend(input)}
              disabled={!canSend}
              className="inline-flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-[#F59E0B] text-[#134E4A] shadow-lg shadow-amber-900/10 disabled:opacity-50"
              aria-label="Send message"
            >
              <FaPaperPlane />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatPanel;
