import React, { createContext, useCallback, useContext, useMemo, useState } from "react";
import Cookies from "js-cookie";
import {
  getAgentConversationKey,
  sendAgentMessage,
} from "../../firebase/agentService";

const ChatContext = createContext(null);

const initialMessages = [
  {
    role: "assistant",
    text:
      "Hi, I am CareBridge AI. I can help with symptoms, precautions, doctors, appointments, lab tests, and hospital contact requests.",
  },
];

export const ChatProvider = ({ children }) => {
  const [messages, setMessages] = useState(initialMessages);
  const [conversationId, setConversationId] = useState(() =>
    window.localStorage.getItem(getAgentConversationKey()) || "",
  );
  const [input, setInput] = useState("");
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");
  const [isOpen, setIsOpen] = useState(false);
  const [pageContext, setPageContext] = useState(null);

  const openChat = useCallback(() => setIsOpen(true), []);
  const closeChat = useCallback(() => setIsOpen(false), []);

  const resetConversation = useCallback(() => {
    window.localStorage.removeItem(getAgentConversationKey());
    setConversationId("");
    setMessages(initialMessages);
    setError("");
  }, []);

  const sendMessage = useCallback(
    async (text, contextOverride = null) => {
      const trimmed = String(text || "").trim();
      if (!trimmed || sending) return;

      const activeContext = contextOverride || pageContext;
      setInput("");
      setError("");
      setSending(true);
      setMessages((current) => [...current, { role: "user", text: trimmed }]);

      try {
        const result = await sendAgentMessage({
          message: trimmed,
          conversationId,
          context: activeContext,
        });
        if (result.conversationId) {
          setConversationId(result.conversationId);
          window.localStorage.setItem(getAgentConversationKey(), result.conversationId);
        }
        setMessages((current) => [
          ...current,
          {
            role: "assistant",
            text: result.reply || "I could not respond right now.",
            actions: result.actions || [],
          },
        ]);
      } catch (requestError) {
        const message =
          requestError?.response?.data?.error ||
          requestError.message ||
          "CareBridge AI is unavailable right now.";
        setError(message);
        setMessages((current) => [
          ...current,
          {
            role: "assistant",
            text: "I could not reach the AI service right now. Please try again after a moment.",
          },
        ]);
      } finally {
        setSending(false);
      }
    },
    [conversationId, pageContext, sending],
  );

  const value = useMemo(
    () => ({
      closeChat,
      error,
      input,
      isOpen,
      messages,
      openChat,
      pageContext,
      resetConversation,
      sendMessage,
      sending,
      setInput,
      setPageContext,
      username: Cookies.get("patient_username") || Cookies.get("username") || "guest",
    }),
    [
      closeChat,
      error,
      input,
      isOpen,
      messages,
      openChat,
      pageContext,
      resetConversation,
      sendMessage,
      sending,
    ],
  );

  return <ChatContext.Provider value={value}>{children}</ChatContext.Provider>;
};

export const useChat = () => {
  const context = useContext(ChatContext);
  if (!context) {
    throw new Error("useChat must be used within a ChatProvider");
  }
  return context;
};
